package com.ashokmart.servlet;
import com.ashokmart.service.AdminProductService; import com.ashokmart.util.DatabaseConnectionPool; import org.slf4j.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/products/view") public final class AdminProductDetailsServlet extends HttpServlet { private static final Logger LOG=LoggerFactory.getLogger(AdminProductDetailsServlet.class); public void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{var admin=AdminWebSupport.authenticatedAdmin(req,res);if(admin==null)return;try{long id=Long.parseLong(req.getParameter("id"));if(id<=0)throw new NumberFormatException();var product=AdminWebSupport.adminProductService(AdminWebSupport.pool(getServletContext())).getProduct(admin.userId(),id);if(product.isEmpty()){res.sendError(404,"Product not found.");return;}req.setAttribute("adminProduct",product.get());req.getRequestDispatcher("/WEB-INF/views/admin-product-details.jsp").forward(req,res);}catch(NumberFormatException e){res.sendError(404,"Product not found.");}catch(IllegalStateException e){LOG.error("Admin product details failed",e);res.sendError(500,"Product details are temporarily unavailable.");}}}
